package it.financemanager.infrastructure.persistence.entity;import jakarta.persistence.*;
@Entity @Table(name="users") public class UserEntity extends JpaBaseEntity {@Column(nullable=false,unique=true,length=254) public String email;@Column(nullable=false) public String password;@Column(nullable=false,length=100) public String name;@Column(nullable=false,length=100) public String surname;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="role_id") public RoleEntity role;protected UserEntity(){}public UserEntity(String e,String p,String n,String s,RoleEntity r){email=e;password=p;name=n;surname=s;role=r;}}
